import * as React from "react";
import { cn } from "@axis-ds/ui-react";
import { AGENT_STATUS_LABELS } from "../constants/a11y-labels";

export interface AgentAvatarProps {
  /** 에이전트 이름 */
  name: string;
  /** 이미지 URL */
  src?: string;
  /** 크기 */
  size?: "sm" | "md" | "lg" | "xl";
  /** 상태 표시 */
  status?: "online" | "busy" | "offline";
  /** 에이전트 타입 */
  type?: "assistant" | "tool" | "system";
  /** 추가 클래스 */
  className?: string;
}

const sizeStyles = {
  sm: "w-6 h-6 text-xs",
  md: "w-8 h-8 text-sm",
  lg: "w-10 h-10 text-base",
  xl: "w-12 h-12 text-lg",
};

const statusStyles = {
  online: "bg-[var(--axis-status-success)]",
  busy: "bg-[var(--axis-status-warning)]",
  offline: "bg-[var(--axis-status-neutral)]",
};

const typeColors = {
  assistant: "bg-[var(--axis-agent-avatar-assistant)]",
  tool: "bg-[var(--axis-agent-avatar-tool)]",
  system: "bg-[var(--axis-agent-avatar-system)]",
};

/**
 * 에이전트 아바타 컴포넌트
 */
export function AgentAvatar({
  name,
  src,
  size = "md",
  status,
  type = "assistant",
  className,
}: AgentAvatarProps) {
  const initials = name
    .split(" ")
    .map((n) => n[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();

  const statusLabel = status ? AGENT_STATUS_LABELS[status] : "";
  const ariaLabel = `${name}${statusLabel ? `, ${statusLabel}` : ""}`;

  return (
    <div
      role="img"
      aria-label={ariaLabel}
      className={cn("relative inline-flex", className)}
    >
      {src ? (
        <img
          src={src}
          alt=""
          aria-hidden="true"
          className={cn(
            "rounded-full object-cover",
            sizeStyles[size]
          )}
        />
      ) : (
        <div
          aria-hidden="true"
          className={cn(
            "rounded-full flex items-center justify-center font-medium text-[var(--axis-agent-avatar-text)]",
            sizeStyles[size],
            typeColors[type]
          )}
        >
          {initials}
        </div>
      )}
      {status && (
        <span
          aria-hidden="true"
          className={cn(
            "absolute bottom-0 right-0 rounded-full border-2 border-[var(--axis-surface-default)]",
            size === "sm" ? "w-2 h-2" : "w-3 h-3",
            statusStyles[status]
          )}
        />
      )}
    </div>
  );
}

import * as React from "react";
import { cn } from "@axis-ds/ui-react";
import { SEVERITY_LABELS } from "../constants/a11y-labels";

export type Severity = "info" | "warning" | "error";

export interface ApprovalAction {
  label: string;
  variant?: "default" | "secondary" | "ghost" | "destructive";
  onClick: () => void;
}

export interface ApprovalCardProps {
  /** 고유 ID (접근성용) */
  id?: string;
  /** 제목 */
  title: string;
  /** 설명 */
  description?: string;
  /** 심각도 (색상 결정) */
  severity?: Severity;
  /** 액션 버튼 목록 */
  actions: ApprovalAction[];
  /** 추가 내용 */
  children?: React.ReactNode;
  /** 추가 클래스 */
  className?: string;
}

const severityStyles: Record<Severity, { border: string; icon: string; bg: string }> = {
  info: {
    border: "border-l-[var(--axis-status-info)]",
    icon: "text-[var(--axis-status-info)]",
    bg: "bg-[var(--axis-surface-info)]",
  },
  warning: {
    border: "border-l-[var(--axis-status-warning)]",
    icon: "text-[var(--axis-status-warning)]",
    bg: "bg-[var(--axis-surface-warning)]",
  },
  error: {
    border: "border-l-[var(--axis-status-error)]",
    icon: "text-[var(--axis-status-error)]",
    bg: "bg-[var(--axis-surface-error)]",
  },
};

const severityIcons: Record<Severity, React.ReactNode> = {
  info: (
    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
    </svg>
  ),
  warning: (
    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
    </svg>
  ),
  error: (
    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
    </svg>
  ),
};

const actionVariantStyles: Record<string, string> = {
  default: "bg-[var(--axis-button-bg-default)] text-[var(--axis-button-text-default)] hover:bg-[var(--axis-button-bg-hover)]",
  secondary: "bg-[var(--axis-button-secondary-bg-default)] text-[var(--axis-text-primary)] hover:bg-[var(--axis-button-secondary-bg-hover)]",
  ghost: "bg-transparent text-[var(--axis-text-primary)] hover:bg-[var(--axis-surface-secondary)]",
  destructive: "bg-[var(--axis-button-destructive-bg-default)] text-[var(--axis-button-destructive-text-default)] hover:bg-[var(--axis-button-destructive-bg-hover)]",
};

/**
 * 사용자 승인이 필요한 작업을 표시하는 카드 컴포넌트
 */
export function ApprovalCard({
  id,
  title,
  description,
  severity = "info",
  actions,
  children,
  className,
}: ApprovalCardProps) {
  const styles = severityStyles[severity];
  const generatedId = React.useId();
  const baseId = id || generatedId;
  const titleId = `${baseId}-title`;
  const descId = `${baseId}-desc`;
  const severityLabel = SEVERITY_LABELS[severity];

  return (
    <div
      role="region"
      aria-labelledby={titleId}
      aria-describedby={description ? descId : undefined}
      className={cn(
        "rounded-lg border border-l-4 p-4",
        "bg-[var(--axis-surface-default)] border-[var(--axis-border-default)]",
        styles.border,
        className
      )}
    >
      <div className="flex items-start gap-3">
        <div className={cn("flex-shrink-0 mt-0.5", styles.icon)} aria-hidden="true">
          {severityIcons[severity]}
        </div>
        <div className="flex-1 min-w-0">
          <span className="sr-only">{severityLabel} 알림:</span>
          <h4 id={titleId} className="text-sm font-semibold text-[var(--axis-text-primary)]">
            {title}
          </h4>
          {description && (
            <p id={descId} className="mt-1 text-sm text-[var(--axis-text-secondary)]">
              {description}
            </p>
          )}
          {children && <div className="mt-3">{children}</div>}
          <div className="flex flex-wrap gap-2 mt-4">
            {actions.map((action, index) => (
              <button
                key={index}
                onClick={action.onClick}
                className={cn(
                  "px-3 py-1.5 text-sm font-medium rounded-md transition-colors",
                  actionVariantStyles[action.variant || "default"]
                )}
              >
                {action.label}
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

import * as React from "react";
import { cn } from "@axis-ds/ui-react";
import { ATTACHMENT_TYPE_LABELS } from "../constants/a11y-labels";

export type AttachmentType = "image" | "document" | "code" | "archive" | "other";
export type AttachmentStatus = "uploading" | "complete" | "error";

export interface AttachmentCardProps {
  /** 파일 타입 */
  type: AttachmentType;
  /** 파일명 */
  name: string;
  /** 파일 크기 (bytes) */
  size?: number;
  /** 파일 URL */
  url?: string;
  /** 썸네일 URL (이미지인 경우) */
  thumbnail?: string;
  /** 업로드 상태 */
  status?: AttachmentStatus;
  /** 업로드 진행률 (0-100) */
  progress?: number;
  /** 삭제 콜백 */
  onRemove?: () => void;
  /** 추가 클래스 */
  className?: string;
}

const typeIcons: Record<AttachmentType, React.ReactNode> = {
  image: (
    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
    </svg>
  ),
  document: (
    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
    </svg>
  ),
  code: (
    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 20l4-16m4 4l4 4-4 4M6 16l-4-4 4-4" />
    </svg>
  ),
  archive: (
    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 8h14M5 8a2 2 0 110-4h14a2 2 0 110 4M5 8v10a2 2 0 002 2h10a2 2 0 002-2V8m-9 4h4" />
    </svg>
  ),
  other: (
    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" />
    </svg>
  ),
};

const formatFileSize = (bytes: number): string => {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
};

/**
 * 파일/이미지 첨부를 표시하는 카드 컴포넌트
 */
export function AttachmentCard({
  type,
  name,
  size,
  url,
  thumbnail,
  status = "complete",
  progress,
  onRemove,
  className,
}: AttachmentCardProps) {
  const typeLabel = ATTACHMENT_TYPE_LABELS[type];

  return (
    <div
      role="article"
      aria-label={`${typeLabel}: ${name}`}
      className={cn(
        "flex items-center gap-3 rounded-lg border p-3",
        "bg-[var(--axis-surface-default)] border-[var(--axis-border-default)]",
        status === "error" && "border-[var(--axis-status-error-border)]",
        className
      )}
    >
      {/* 썸네일 또는 아이콘 */}
      {thumbnail ? (
        <img
          src={thumbnail}
          alt=""
          aria-hidden="true"
          className="w-10 h-10 rounded object-cover flex-shrink-0"
        />
      ) : (
        <div
          className="w-10 h-10 rounded flex items-center justify-center flex-shrink-0 bg-[var(--axis-surface-secondary)] text-[var(--axis-icon-secondary)]"
          aria-hidden="true"
        >
          {typeIcons[type]}
        </div>
      )}

      {/* 정보 */}
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium text-[var(--axis-text-primary)] truncate">
          {url ? (
            <a
              href={url}
              target="_blank"
              rel="noopener noreferrer"
              className="hover:underline"
              aria-label={`${name} (새 창에서 열림)`}
            >
              {name}
            </a>
          ) : (
            name
          )}
        </p>
        <div className="flex items-center gap-2 text-xs text-[var(--axis-text-tertiary)]">
          <span>{typeLabel}</span>
          {size !== undefined && (
            <>
              <span aria-hidden="true">·</span>
              <span>{formatFileSize(size)}</span>
            </>
          )}
          {status === "error" && (
            <span className="text-[var(--axis-text-error)]">업로드 실패</span>
          )}
        </div>

        {/* 업로드 진행률 */}
        {status === "uploading" && progress !== undefined && (
          <div className="mt-1.5 h-1 rounded-full bg-[var(--axis-surface-secondary)] overflow-hidden">
            <div
              className="h-full rounded-full bg-[var(--axis-status-running)] transition-all"
              style={{ width: `${progress}%` }}
              role="progressbar"
              aria-valuenow={progress}
              aria-valuemin={0}
              aria-valuemax={100}
              aria-label="업로드 진행률"
            />
          </div>
        )}
      </div>

      {/* 삭제 버튼 */}
      {onRemove && (
        <button
          onClick={onRemove}
          aria-label={`${name} 삭제`}
          className="flex-shrink-0 p-1 rounded-md text-[var(--axis-text-tertiary)] hover:text-[var(--axis-text-secondary)] hover:bg-[var(--axis-surface-secondary)] transition-colors"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>
      )}
    </div>
  );
}

import * as React from "react";
import { cn } from "@axis-ds/ui-react";

export interface CodeBlockProps {
  /** 코드 문자열 */
  code: string;
  /** 언어 (구문 강조용 힌트) */
  language?: string;
  /** 파일명 */
  filename?: string;
  /** 줄 번호 표시 */
  showLineNumbers?: boolean;
  /** 복사 완료 콜백 */
  onCopy?: (code: string) => void;
  /** 최대 높이 (스크롤) */
  maxHeight?: string;
  /** 추가 클래스 */
  className?: string;
}

/**
 * 코드 표시 + 복사 버튼 컴포넌트
 */
export function CodeBlock({
  code,
  language,
  filename,
  showLineNumbers = false,
  onCopy,
  maxHeight,
  className,
}: CodeBlockProps) {
  const [copied, setCopied] = React.useState(false);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      onCopy?.(code);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // clipboard API 미지원 시 fallback 없음
    }
  };

  const lines = code.split("\n");

  return (
    <div
      className={cn(
        "rounded-lg border overflow-hidden",
        "bg-[var(--axis-surface-default)] border-[var(--axis-border-default)]",
        className
      )}
    >
      {/* 헤더 */}
      <div className="flex items-center justify-between px-3 py-2 border-b border-[var(--axis-border-default)] bg-[var(--axis-surface-secondary)]">
        <div className="flex items-center gap-2 min-w-0">
          {filename && (
            <code className="text-xs font-mono text-[var(--axis-text-primary)] truncate">
              {filename}
            </code>
          )}
          {language && (
            <span className="text-xs px-1.5 py-0.5 rounded bg-[var(--axis-surface-tertiary)] text-[var(--axis-text-tertiary)]">
              {language}
            </span>
          )}
        </div>
        <button
          onClick={handleCopy}
          aria-label={copied ? "복사됨" : "코드 복사"}
          className="flex items-center gap-1 px-2 py-1 text-xs rounded-md text-[var(--axis-text-secondary)] hover:bg-[var(--axis-surface-tertiary)] transition-colors"
        >
          {copied ? (
            <>
              <svg className="w-3.5 h-3.5 text-[var(--axis-status-success)]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
              </svg>
              <span>복사됨</span>
            </>
          ) : (
            <>
              <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" />
              </svg>
              <span>복사</span>
            </>
          )}
        </button>
      </div>

      {/* 코드 본문 */}
      <div
        className="overflow-auto"
        style={maxHeight ? { maxHeight } : undefined}
      >
        <pre className="p-3 text-sm leading-relaxed">
          <code className="text-[var(--axis-text-primary)] font-mono">
            {showLineNumbers ? (
              <table className="border-collapse w-full" role="presentation">
                <tbody>
                  {lines.map((line, i) => (
                    <tr key={i}>
                      <td
                        className="select-none text-right pr-4 text-[var(--axis-text-tertiary)] w-8"
                        aria-hidden="true"
                      >
                        {i + 1}
                      </td>
                      <td className="whitespace-pre">{line}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            ) : (
              code
            )}
          </code>
        </pre>
      </div>
    </div>
  );
}

import * as React from "react";
import { cn } from "@axis-ds/ui-react";

export interface ModelInfo {
  /** 모델 이름 */
  name: string;
  /** 모델 제공자 */
  provider?: string;
  /** 모델 버전 */
  version?: string;
}

export interface ContextPanelProps {
  /** 모델 정보 */
  modelInfo?: ModelInfo;
  /** 시스템 프롬프트 */
  systemPrompt?: string;
  /** 첨부 파일 목록 */
  attachedFiles?: string[];
  /** 추가 설정 키-값 */
  settings?: Record<string, string>;
  /** 접힘 가능 여부 */
  collapsible?: boolean;
  /** 기본 펼침 상태 */
  defaultExpanded?: boolean;
  /** 추가 클래스 */
  className?: string;
}

/**
 * 모델/설정 메타 정보를 표시하는 패널 컴포넌트
 */
export function ContextPanel({
  modelInfo,
  systemPrompt,
  attachedFiles,
  settings,
  collapsible = true,
  defaultExpanded = false,
  className,
}: ContextPanelProps) {
  const [isExpanded, setIsExpanded] = React.useState(defaultExpanded);
  const contentId = React.useId();

  const hasContent = modelInfo || systemPrompt || (attachedFiles && attachedFiles.length > 0) || (settings && Object.keys(settings).length > 0);
  if (!hasContent) return null;

  const header = (
    <div className="flex items-center gap-2">
      <svg className="w-4 h-4 text-[var(--axis-icon-secondary)]" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.066 2.573c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.573 1.066c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.066-2.573c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
      </svg>
      <span className="text-xs font-medium text-[var(--axis-text-secondary)]">컨텍스트</span>
    </div>
  );

  const content = (
    <div id={contentId} className="space-y-3 mt-2">
      {modelInfo && (
        <div>
          <h5 className="text-xs font-medium text-[var(--axis-text-secondary)] mb-1">모델</h5>
          <div className="flex items-center gap-2">
            <code className="text-sm font-mono text-[var(--axis-text-primary)]">{modelInfo.name}</code>
            {modelInfo.provider && (
              <span className="text-xs text-[var(--axis-text-tertiary)]">{modelInfo.provider}</span>
            )}
            {modelInfo.version && (
              <span className="text-xs px-1.5 py-0.5 rounded bg-[var(--axis-surface-tertiary)] text-[var(--axis-text-tertiary)]">
                {modelInfo.version}
              </span>
            )}
          </div>
        </div>
      )}

      {systemPrompt && (
        <div>
          <h5 className="text-xs font-medium text-[var(--axis-text-secondary)] mb-1">시스템 프롬프트</h5>
          <p className="text-xs text-[var(--axis-text-primary)] p-2 rounded bg-[var(--axis-surface-secondary)] line-clamp-3 whitespace-pre-wrap">
            {systemPrompt}
          </p>
        </div>
      )}

      {attachedFiles && attachedFiles.length > 0 && (
        <div>
          <h5 className="text-xs font-medium text-[var(--axis-text-secondary)] mb-1">
            첨부 파일 ({attachedFiles.length})
          </h5>
          <div className="space-y-1">
            {attachedFiles.map((file, i) => (
              <div key={i} className="flex items-center gap-1.5 text-xs text-[var(--axis-text-primary)]">
                <svg className="w-3 h-3 text-[var(--axis-icon-secondary)]" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" />
                </svg>
                <span className="truncate">{file}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {settings && Object.keys(settings).length > 0 && (
        <div>
          <h5 className="text-xs font-medium text-[var(--axis-text-secondary)] mb-1">설정</h5>
          <div className="space-y-1">
            {Object.entries(settings).map(([key, value]) => (
              <div key={key} className="flex items-center justify-between text-xs">
                <span className="text-[var(--axis-text-secondary)]">{key}</span>
                <code className="font-mono text-[var(--axis-text-primary)]">{value}</code>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );

  return (
    <div
      className={cn(
        "rounded-lg border p-3",
        "bg-[var(--axis-surface-secondary)] border-[var(--axis-border-default)]",
        className
      )}
    >
      {collapsible ? (
        <>
          <button
            onClick={() => setIsExpanded(!isExpanded)}
            aria-expanded={isExpanded}
            aria-controls={contentId}
            className="w-full flex items-center justify-between hover:opacity-80 transition-opacity"
          >
            {header}
            <svg
              className={cn(
                "w-4 h-4 text-[var(--axis-text-secondary)] transition-transform",
                isExpanded && "rotate-180"
              )}
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
              aria-hidden="true"
            >
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
            </svg>
          </button>
          {isExpanded && content}
        </>
      ) : (
        <>
          {header}
          {content}
        </>
      )}
    </div>
  );
}

import * as React from "react";
import { cn } from "@axis-ds/ui-react";
import { DIFF_LABELS } from "../constants/a11y-labels";

export type DiffViewMode = "unified" | "split";

export interface DiffViewerProps {
  /** 변경 전 코드 */
  before: string;
  /** 변경 후 코드 */
  after: string;
  /** 파일명 */
  filename?: string;
  /** 표시 모드 */
  viewMode?: DiffViewMode;
  /** 추가 클래스 */
  className?: string;
}

type DiffLineType = "added" | "removed" | "unchanged";

interface DiffLine {
  type: DiffLineType;
  content: string;
  oldLineNumber?: number;
  newLineNumber?: number;
}

/** LCS 기반 diff 알고리즘 */
function computeDiff(before: string, after: string): DiffLine[] {
  const oldLines = before.split("\n");
  const newLines = after.split("\n");
  const m = oldLines.length;
  const n = newLines.length;

  // LCS 테이블 구축
  const dp: number[][] = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (oldLines[i - 1] === newLines[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }

  // 역추적으로 diff 생성
  const result: DiffLine[] = [];
  let i = m;
  let j = n;

  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && oldLines[i - 1] === newLines[j - 1]) {
      result.unshift({ type: "unchanged", content: oldLines[i - 1], oldLineNumber: i, newLineNumber: j });
      i--;
      j--;
    } else if (j > 0 && (i === 0 || dp[i][j - 1] >= dp[i - 1][j])) {
      result.unshift({ type: "added", content: newLines[j - 1], newLineNumber: j });
      j--;
    } else if (i > 0) {
      result.unshift({ type: "removed", content: oldLines[i - 1], oldLineNumber: i });
      i--;
    }
  }

  return result;
}

const lineTypeStyles: Record<DiffLineType, string> = {
  added: "bg-[color:color-mix(in_srgb,var(--axis-diff-added)_10%,transparent)]",
  removed: "bg-[color:color-mix(in_srgb,var(--axis-diff-removed)_10%,transparent)]",
  unchanged: "",
};

const lineTypeTextStyles: Record<DiffLineType, string> = {
  added: "text-[var(--axis-diff-added-text)]",
  removed: "text-[var(--axis-diff-removed-text)]",
  unchanged: "text-[var(--axis-text-primary)]",
};

const lineTypeSymbols: Record<DiffLineType, string> = {
  added: "+",
  removed: "-",
  unchanged: " ",
};

/**
 * 코드 변경사항 비교 표시 컴포넌트
 */
export function DiffViewer({
  before,
  after,
  filename,
  viewMode = "unified",
  className,
}: DiffViewerProps) {
  const [mode, setMode] = React.useState<DiffViewMode>(viewMode);
  const diffLines = React.useMemo(() => computeDiff(before, after), [before, after]);

  const addedCount = diffLines.filter((l) => l.type === "added").length;
  const removedCount = diffLines.filter((l) => l.type === "removed").length;

  return (
    <div
      role="region"
      aria-label={filename ? `${filename} 변경사항` : "코드 변경사항"}
      className={cn(
        "rounded-lg border overflow-hidden",
        "bg-[var(--axis-surface-default)] border-[var(--axis-border-default)]",
        className
      )}
    >
      {/* 헤더 */}
      <div className="flex items-center justify-between px-3 py-2 border-b border-[var(--axis-border-default)] bg-[var(--axis-surface-secondary)]">
        <div className="flex items-center gap-2 min-w-0">
          <svg className="w-4 h-4 text-[var(--axis-icon-secondary)]" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h7" />
          </svg>
          {filename && (
            <code className="text-xs font-mono text-[var(--axis-text-primary)] truncate">{filename}</code>
          )}
          <span className="text-xs text-[var(--axis-diff-added)]" aria-label={`${addedCount}줄 ${DIFF_LABELS.added}`}>
            +{addedCount}
          </span>
          <span className="text-xs text-[var(--axis-diff-removed)]" aria-label={`${removedCount}줄 ${DIFF_LABELS.removed}`}>
            -{removedCount}
          </span>
        </div>
        <div className="flex items-center gap-1 bg-[var(--axis-surface-tertiary)] rounded-md p-0.5">
          <button
            onClick={() => setMode("unified")}
            aria-pressed={mode === "unified"}
            className={cn(
              "px-2 py-0.5 text-xs rounded transition-colors",
              mode === "unified"
                ? "bg-[var(--axis-surface-default)] text-[var(--axis-text-primary)] shadow-sm"
                : "text-[var(--axis-text-tertiary)] hover:text-[var(--axis-text-secondary)]"
            )}
          >
            통합
          </button>
          <button
            onClick={() => setMode("split")}
            aria-pressed={mode === "split"}
            className={cn(
              "px-2 py-0.5 text-xs rounded transition-colors",
              mode === "split"
                ? "bg-[var(--axis-surface-default)] text-[var(--axis-text-primary)] shadow-sm"
                : "text-[var(--axis-text-tertiary)] hover:text-[var(--axis-text-secondary)]"
            )}
          >
            분할
          </button>
        </div>
      </div>

      {/* Diff 본문 */}
      <div className="overflow-auto">
        {mode === "unified" ? (
          <UnifiedView lines={diffLines} />
        ) : (
          <SplitView lines={diffLines} />
        )}
      </div>
    </div>
  );
}

function UnifiedView({ lines }: { lines: DiffLine[] }) {
  return (
    <table className="w-full text-xs font-mono border-collapse" role="presentation">
      <tbody>
        {lines.map((line, i) => (
          <tr key={i} className={lineTypeStyles[line.type]}>
            <td className="select-none text-right px-2 py-0.5 text-[var(--axis-text-tertiary)] w-10 border-r border-[var(--axis-border-default)]">
              {line.oldLineNumber ?? ""}
            </td>
            <td className="select-none text-right px-2 py-0.5 text-[var(--axis-text-tertiary)] w-10 border-r border-[var(--axis-border-default)]">
              {line.newLineNumber ?? ""}
            </td>
            <td className={cn("select-none w-4 text-center py-0.5", lineTypeTextStyles[line.type])}>
              {lineTypeSymbols[line.type]}
            </td>
            <td className={cn("px-2 py-0.5 whitespace-pre", lineTypeTextStyles[line.type])}>
              {line.content}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function SplitView({ lines }: { lines: DiffLine[] }) {
  // 왼쪽: removed + unchanged, 오른쪽: added + unchanged
  const leftLines: (DiffLine | null)[] = [];
  const rightLines: (DiffLine | null)[] = [];

  for (const line of lines) {
    if (line.type === "unchanged") {
      leftLines.push(line);
      rightLines.push(line);
    } else if (line.type === "removed") {
      leftLines.push(line);
      rightLines.push(null);
    } else {
      leftLines.push(null);
      rightLines.push(line);
    }
  }

  return (
    <table className="w-full text-xs font-mono border-collapse" role="presentation">
      <tbody>
        {leftLines.map((leftLine, i) => {
          const rightLine = rightLines[i];
          return (
            <tr key={i}>
              {/* 왼쪽 (before) */}
              <td className={cn("select-none text-right px-2 py-0.5 text-[var(--axis-text-tertiary)] w-10 border-r border-[var(--axis-border-default)]", leftLine ? lineTypeStyles[leftLine.type] : "")}>
                {leftLine?.oldLineNumber ?? ""}
              </td>
              <td className={cn("select-none w-4 text-center py-0.5", leftLine ? lineTypeTextStyles[leftLine.type] : "")}>
                {leftLine ? lineTypeSymbols[leftLine.type] : ""}
              </td>
              <td className={cn("px-2 py-0.5 whitespace-pre w-1/2 border-r border-[var(--axis-border-default)]", leftLine ? cn(lineTypeStyles[leftLine.type], lineTypeTextStyles[leftLine.type]) : "")}>
                {leftLine?.content ?? ""}
              </td>
              {/* 오른쪽 (after) */}
              <td className={cn("select-none text-right px-2 py-0.5 text-[var(--axis-text-tertiary)] w-10 border-r border-[var(--axis-border-default)]", rightLine ? lineTypeStyles[rightLine.type] : "")}>
                {rightLine?.newLineNumber ?? ""}
              </td>
              <td className={cn("select-none w-4 text-center py-0.5", rightLine ? lineTypeTextStyles[rightLine.type] : "")}>
                {rightLine ? lineTypeSymbols[rightLine.type] : ""}
              </td>
              <td className={cn("px-2 py-0.5 whitespace-pre w-1/2", rightLine ? cn(lineTypeStyles[rightLine.type], lineTypeTextStyles[rightLine.type]) : "")}>
                {rightLine?.content ?? ""}
              </td>
            </tr>
          );
        })}
      </tbody>
    </table>
  );
}

import * as React from "react";
import { cn } from "@axis-ds/ui-react";
import { FEEDBACK_LABELS } from "../constants/a11y-labels";

export type FeedbackType = "like" | "dislike" | "none";

export interface FeedbackButtonsProps {
  /** 메시지 ID */
  messageId: string;
  /** 초기 피드백 상태 */
  initialFeedback?: FeedbackType;
  /** 피드백 변경 콜백 */
  onFeedback?: (messageId: string, feedback: FeedbackType) => void;
  /** 크기 */
  size?: "sm" | "md";
  /** 추가 클래스 */
  className?: string;
}

const sizeStyles = {
  sm: "p-1",
  md: "p-1.5",
};

const iconSizes = {
  sm: "w-3.5 h-3.5",
  md: "w-4 h-4",
};

/**
 * 좋아요/싫어요 피드백 버튼 컴포넌트
 */
export function FeedbackButtons({
  messageId,
  initialFeedback = "none",
  onFeedback,
  size = "sm",
  className,
}: FeedbackButtonsProps) {
  const [feedback, setFeedback] = React.useState<FeedbackType>(initialFeedback);

  const handleFeedback = (type: FeedbackType) => {
    const newFeedback = feedback === type ? "none" : type;
    setFeedback(newFeedback);
    onFeedback?.(messageId, newFeedback);
  };

  return (
    <div
      role="group"
      aria-label="메시지 피드백"
      className={cn("inline-flex items-center gap-1", className)}
    >
      <button
        onClick={() => handleFeedback("like")}
        aria-pressed={feedback === "like"}
        aria-label={FEEDBACK_LABELS.like}
        className={cn(
          "rounded-md transition-colors",
          sizeStyles[size],
          feedback === "like"
            ? "text-[var(--axis-status-success)] bg-[color:color-mix(in_srgb,var(--axis-status-success)_10%,transparent)]"
            : "text-[var(--axis-text-tertiary)] hover:text-[var(--axis-text-secondary)] hover:bg-[var(--axis-surface-secondary)]"
        )}
      >
        <svg className={iconSizes[size]} fill={feedback === "like" ? "currentColor" : "none"} stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 9V5a3 3 0 00-3-3l-4 9v11h11.28a2 2 0 002-1.7l1.38-9a2 2 0 00-2-2.3H14zm-9 11H3a2 2 0 01-2-2v-7a2 2 0 012-2h2" />
        </svg>
      </button>
      <button
        onClick={() => handleFeedback("dislike")}
        aria-pressed={feedback === "dislike"}
        aria-label={FEEDBACK_LABELS.dislike}
        className={cn(
          "rounded-md transition-colors",
          sizeStyles[size],
          feedback === "dislike"
            ? "text-[var(--axis-status-error)] bg-[color:color-mix(in_srgb,var(--axis-status-error)_10%,transparent)]"
            : "text-[var(--axis-text-tertiary)] hover:text-[var(--axis-text-secondary)] hover:bg-[var(--axis-surface-secondary)]"
        )}
      >
        <svg className={iconSizes[size]} fill={feedback === "dislike" ? "currentColor" : "none"} stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 15V19a3 3 0 003 3l4-9V2H5.72a2 2 0 00-2 1.7l-1.38 9a2 2 0 002 2.3H10zm9-13h2a2 2 0 012 2v7a2 2 0 01-2 2h-2" />
        </svg>
      </button>
    </div>
  );
}

import * as React from "react";
import { cn } from "@axis-ds/ui-react";
import { MESSAGE_ROLE_LABELS } from "../constants/a11y-labels";

export type MessageRole = "user" | "assistant" | "system";
export type MessageStatus = "sending" | "sent" | "error";

export interface MessageBubbleProps {
  /** 메시지 역할 */
  role: MessageRole;
  /** 메시지 내용 */
  content: React.ReactNode;
  /** 타임스탬프 */
  timestamp?: Date;
  /** 아바타 (ReactNode 또는 이미지 URL) */
  avatar?: React.ReactNode | string;
  /** 전송 상태 */
  status?: MessageStatus;
  /** 하단 액션 영역 */
  actions?: React.ReactNode;
  /** 메타데이터 (모델명 등) */
  metadata?: string;
  /** 추가 클래스 */
  className?: string;
}

const roleStyles: Record<MessageRole, { container: string; bubble: string }> = {
  user: {
    container: "flex-row-reverse",
    bubble: "bg-[var(--axis-agent-message-user-bg)] text-[var(--axis-agent-message-user-text)] rounded-br-sm",
  },
  assistant: {
    container: "flex-row",
    bubble: "bg-[var(--axis-surface-secondary)] text-[var(--axis-text-primary)] rounded-bl-sm",
  },
  system: {
    container: "justify-center",
    bubble: "bg-[var(--axis-surface-tertiary)] text-[var(--axis-text-secondary)] text-xs italic",
  },
};

const statusIcons: Record<MessageStatus, React.ReactNode> = {
  sending: (
    <svg className="w-3 h-3 animate-spin motion-reduce:!animate-none" viewBox="0 0 24 24" fill="none">
      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
    </svg>
  ),
  sent: (
    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
    </svg>
  ),
  error: (
    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01" />
    </svg>
  ),
};

/**
 * 대화 메시지 버블 컴포넌트
 */
export function MessageBubble({
  role,
  content,
  timestamp,
  avatar,
  status,
  actions,
  metadata,
  className,
}: MessageBubbleProps) {
  const roleLabel = MESSAGE_ROLE_LABELS[role];

  const renderAvatar = () => {
    if (!avatar) return null;
    if (typeof avatar === "string") {
      return (
        <img
          src={avatar}
          alt=""
          aria-hidden="true"
          className="w-8 h-8 rounded-full object-cover flex-shrink-0"
        />
      );
    }
    return <div className="flex-shrink-0">{avatar}</div>;
  };

  return (
    <div
      role="article"
      aria-label={`${roleLabel} 메시지`}
      className={cn("flex items-start gap-2", roleStyles[role].container, className)}
    >
      {role !== "system" && renderAvatar()}
      <div className={cn("max-w-[80%]", role === "system" && "max-w-full")}>
        <div
          className={cn(
            "rounded-lg px-3 py-2",
            roleStyles[role].bubble
          )}
        >
          <div className="text-sm whitespace-pre-wrap">{content}</div>
        </div>
        <div className="flex items-center gap-2 mt-1 px-1">
          {timestamp && (
            <time
              dateTime={timestamp.toISOString()}
              className="text-xs text-[var(--axis-text-tertiary)]"
            >
              {timestamp.toLocaleTimeString("ko-KR", { hour: "2-digit", minute: "2-digit" })}
            </time>
          )}
          {metadata && (
            <span className="text-xs text-[var(--axis-text-tertiary)]">{metadata}</span>
          )}
          {status && (
            <span
              className={cn(
                "text-[var(--axis-text-tertiary)]",
                status === "error" && "text-[var(--axis-text-error)]"
              )}
              aria-label={status === "sending" ? "전송 중" : status === "sent" ? "전송됨" : "전송 실패"}
            >
              {statusIcons[status]}
            </span>
          )}
        </div>
        {actions && <div className="mt-1">{actions}</div>}
      </div>
    </div>
  );
}

