  showCursor?: boolean;
  /** 완료 콜백 */
  onComplete?: () => void;
  /** 추가 클래스 */
  className?: string;
}

/**
 * 텍스트를 실시간으로 스트리밍하는 컴포넌트
 * AI 응답을 타이핑 효과로 표시할 때 사용
 */
export function StreamingText({
  text,
  speed = 20,
  isComplete = false,
  showCursor = true,
  onComplete,
  "aria-live": ariaLive,
  "aria-label": ariaLabel,
  className,
}: StreamingTextProps) {
  // 글자는 코드 포인트 단위로 센다(이모지 등 서로게이트 쌍을 반쪽으로 보이지 않게)
  const chars = React.useMemo(() => Array.from(text), [text]);
  // 상태는 "보여 줄 글자 수"만 두고 화면 문자열은 text 에서 잘라 만든다.
  // effect 가 정리 후 다시 실행돼도(StrictMode · 부모 재렌더) 이 위치에서 이어 간다.
  const [visibleLength, setVisibleLength] = React.useState(0);
  const [prevText, setPrevText] = React.useState(text);
  // text 변경: 이어 붙이기면 진행 위치 유지, 통째 교체면 처음부터(렌더 중 상태 조정)
  if (text !== prevText) {
    setPrevText(text);
    if (!text.startsWith(prevText)) setVisibleLength(0);
  }

  const targetLength = chars.length;
  const isStreaming = !isComplete && visibleLength < targetLength;

  // onComplete 는 ref 로 읽어 effect 의존성에서 뺀다(부모가 매 렌더 새 함수를 넘겨도 진행 유지)
  const onCompleteRef = React.useRef(onComplete);
  React.useEffect(() => {
    onCompleteRef.current = onComplete;
  });

  React.useEffect(() => {
    if (!isStreaming) return;
    const interval = setInterval(() => {
      setVisibleLength((n) => Math.min(n + 1, targetLength));
    }, speed);
    return () => clearInterval(interval);
  }, [isStreaming, targetLength, speed]);

  // 화면이 text 끝까지 따라잡은 순간 한 번 onComplete 를 부른다(isComplete 로 즉시 표시한 경우는 제외)
  const wasStreamingRef = React.useRef(false);
  React.useEffect(() => {
    if (isStreaming) {
      wasStreamingRef.current = true;
      return;
    }
    if (wasStreamingRef.current) {
      wasStreamingRef.current = false;
      if (!isComplete) onCompleteRef.current?.();
    }
  }, [isStreaming, isComplete]);

  const displayedText = isComplete ? text : chars.slice(0, visibleLength).join("");

  return (
    <div
      role="region"
      aria-label={ariaLabel || "AI 응답"}
      aria-live={ariaLive ?? "polite"}
      aria-busy={isStreaming}
      className={cn("relative", className)}
    >
      <span className="text-[var(--axis-text-primary)] whitespace-pre-wrap">
        {displayedText}
      </span>
      {showCursor && isStreaming && (
        <span className="inline-block w-0.5 h-4 ml-0.5 bg-[var(--axis-text-primary)] animate-pulse motion-reduce:!animate-none" aria-hidden="true" />
      )}
    </div>
  );
}

import * as React from "react";
import { cn } from "@axis-ds/ui-react";

export type SurfaceType = "text" | "code" | "table" | "chart" | "form" | "custom";

export interface Surface {
  id: string;
  type: SurfaceType;
  title?: string;
  content: unknown;
  metadata?: Record<string, unknown>;
}

export interface SurfaceRendererProps {
  surface: Surface;
  renderCustom?: (surface: Surface) => React.ReactNode;
  className?: string;
}

/**
 * 다양한 타입의 Surface를 동적으로 렌더링하는 컴포넌트
 */
export function SurfaceRenderer({
  surface,
  renderCustom,
  className,
}: SurfaceRendererProps) {
  const renderContent = () => {
    switch (surface.type) {
      case "text":
        return (
          <div className="text-sm text-[var(--axis-text-primary)]">
            {String(surface.content)}
          </div>
        );

      case "code":
        return (
          <pre className="p-3 rounded-md bg-[var(--axis-surface-secondary)] overflow-x-auto">
            <code className="text-sm font-mono text-[var(--axis-text-primary)]">
              {String(surface.content)}
            </code>
          </pre>
        );

      case "table": {
        const tableData = surface.content as { headers: string[]; rows: string[][] };
        return (
          <div className="overflow-x-auto">
            <table role="table" className="w-full text-sm">
              {surface.title && (
                <caption className="sr-only">{surface.title}</caption>
              )}
              <thead>
                <tr className="border-b border-[var(--axis-border-default)]">
                  {tableData.headers.map((header, i) => (
                    <th
                      key={i}
                      scope="col"
                      className="px-3 py-2 text-left font-medium text-[var(--axis-text-secondary)]"
                    >
                      {header}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {tableData.rows.map((row, i) => (
                  <tr
                    key={i}
                    className="border-b border-[var(--axis-border-default)] last:border-0"
                  >
                    {row.map((cell, j) => (
                      <td
                        key={j}
                        className="px-3 py-2 text-[var(--axis-text-primary)]"
                      >
                        {cell}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        );
      }

      case "chart":
        return (
          <div className="p-4 text-center text-[var(--axis-text-secondary)]">
            [차트: {surface.title || "데이터 시각화"}]
          </div>
        );

      case "form":
        return (
          <div className="p-4 text-center text-[var(--axis-text-secondary)]">
            [폼: {surface.title || "입력 양식"}]
          </div>
        );

      case "custom":
        if (renderCustom) {
          return renderCustom(surface);
        }
        return (
          <div className="p-4 text-center text-[var(--axis-text-secondary)]">
            [커스텀 Surface]
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div
      className={cn(
        "rounded-lg border p-4",
        "bg-[var(--axis-surface-default)] border-[var(--axis-border-default)]",
        className
      )}
    >
      {surface.title && (
        <h4 className="text-sm font-medium text-[var(--axis-text-primary)] mb-3">
          {surface.title}
        </h4>
      )}
      {renderContent()}
    </div>
  );
}

import * as React from "react";
import { cn } from "@axis-ds/ui-react";

export interface ThinkingIndicatorProps {
  /** 표시할 텍스트 */
  text?: string;
  /** 크기 */
  size?: "sm" | "md" | "lg";
  /** 추가 클래스 */
  className?: string;
}

const sizeStyles = {
  sm: "text-xs gap-1",
  md: "text-sm gap-1.5",
  lg: "text-base gap-2",
};

const dotSizes = {
  sm: "w-1 h-1",
  md: "w-1.5 h-1.5",
  lg: "w-2 h-2",
};

/**
 * AI가 생각 중임을 표시하는 인디케이터
 */
export function ThinkingIndicator({
  text = "생각 중",
  size = "md",
  className,
}: ThinkingIndicatorProps) {
  return (
    <div
      role="status"
      aria-live="polite"
      aria-label={text}
      className={cn(
        "flex items-center text-[var(--axis-text-secondary)]",
        sizeStyles[size],
        className
      )}
    >
      <span>{text}</span>
      <div className="flex gap-0.5" aria-hidden="true">
        {[0, 1, 2].map((i) => (
          <div
            key={i}
            className={cn(
              "rounded-full bg-current animate-bounce motion-reduce:!animate-none",
              dotSizes[size]
            )}
            style={{ animationDelay: `${i * 150}ms` }}
          />
        ))}
      </div>
    </div>
  );
}

import * as React from "react";
import { cn } from "@axis-ds/ui-react";

export interface TokenUsageIndicatorProps {
  /** 현재 사용 토큰 수 */
  current: number;
  /** 최대 토큰 수 */
  max: number;
  /** 비용 (USD) */
  cost?: number;
  /** 경고 임계치 (0-1, 기본 0.8) */
  warningThreshold?: number;
  /** 컴팩트 모드 */
  compact?: boolean;
  /** 추가 클래스 */
  className?: string;
}

/**
 * 토큰 사용량 및 비용 표시 컴포넌트
 */
export function TokenUsageIndicator({
  current,
  max,
  cost,
  warningThreshold = 0.8,
  compact = false,
  className,
}: TokenUsageIndicatorProps) {
  const ratio = max > 0 ? current / max : 0;
  const percentage = Math.min(Math.round(ratio * 100), 100);

  const getColor = () => {
    if (ratio >= 1) return "bg-[var(--axis-status-error)]";
    if (ratio >= warningThreshold) return "bg-[var(--axis-status-warning)]";
    return "bg-[var(--axis-status-success)]";
  };

  const getTextColor = () => {
    if (ratio >= 1) return "text-[var(--axis-status-error)]";
    if (ratio >= warningThreshold) return "text-[var(--axis-status-warning)]";
    return "text-[var(--axis-text-secondary)]";
  };

  const formatNumber = (n: number) =>
    n >= 1000 ? `${(n / 1000).toFixed(1)}k` : String(n);

  if (compact) {
    return (
      <span
        role="meter"
        aria-valuenow={current}
        aria-valuemin={0}
        aria-valuemax={max}
        aria-label={`토큰 사용량: ${current} / ${max}`}
        className={cn("inline-flex items-center gap-1 text-xs", getTextColor(), className)}
      >
        <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
        </svg>
        {formatNumber(current)}/{formatNumber(max)}
        {cost !== undefined && (
          <span className="text-[var(--axis-text-tertiary)]">(${cost.toFixed(4)})</span>
        )}
      </span>
    );
  }

  return (
    <div
      role="meter"
      aria-valuenow={current}
      aria-valuemin={0}
      aria-valuemax={max}
      aria-label={`토큰 사용량: ${current} / ${max} (${percentage}%)`}
      className={cn("space-y-1", className)}
    >
      <div className="flex items-center justify-between text-xs">
        <span className="text-[var(--axis-text-secondary)]">토큰 사용량</span>
        <span className={getTextColor()}>
          {formatNumber(current)} / {formatNumber(max)}
        </span>
      </div>
      <div className="h-1.5 rounded-full bg-[var(--axis-surface-secondary)] overflow-hidden">
        <div
          className={cn("h-full rounded-full transition-all", getColor())}
          style={{ width: `${percentage}%` }}
          aria-hidden="true"
        />
      </div>
      {cost !== undefined && (
        <div className="text-xs text-[var(--axis-text-tertiary)] text-right">
          ${cost.toFixed(4)}
        </div>
      )}
    </div>
  );
}

import * as React from "react";
import { cn } from "@axis-ds/ui-react";
import { STATUS_LABELS } from "../constants/a11y-labels";

export type ToolStatus = "pending" | "running" | "success" | "error";

export interface ToolCallCardProps {
  /** 도구 이름 */
  toolName: string;
  /** 도구 설명 */
  description?: string;
  /** 실행 상태 */
  status: ToolStatus;
  /** 입력 파라미터 */
  input?: Record<string, unknown>;
  /** 출력 결과 */
  output?: unknown;
  /** 에러 메시지 */
  error?: string;
  /** 실행 시간 (ms) */
  duration?: number;
  /** 펼침 상태 */
  defaultExpanded?: boolean;
  /** 접근성 레이블 */
  "aria-label"?: string;
  /** 추가 클래스 */
  className?: string;
}

const statusConfig: Record<ToolStatus, { color: string; icon: React.ReactNode }> = {
  pending: {
    color: "text-[var(--axis-status-neutral)]",
    icon: (
      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <circle cx="12" cy="12" r="10" strokeWidth={2} />
      </svg>
    ),
  },
  running: {
    color: "text-[var(--axis-status-running)]",
    icon: (
      <svg className="w-4 h-4 animate-spin motion-reduce:!animate-none" viewBox="0 0 24 24" fill="none">
        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
      </svg>
    ),
  },
  success: {
    color: "text-[var(--axis-status-success)]",
    icon: (
      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
      </svg>
    ),
  },
  error: {
    color: "text-[var(--axis-status-error)]",
    icon: (
      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
      </svg>
    ),
  },
};

/**
 * AI 도구 호출 정보를 표시하는 카드 컴포넌트
 */
export function ToolCallCard({
  toolName,
  description,
  status,
  input,
  output,
  error,
  duration,
  defaultExpanded = false,
  "aria-label": ariaLabel,
  className,
}: ToolCallCardProps) {
  const [isExpanded, setIsExpanded] = React.useState(defaultExpanded);
  const config = statusConfig[status];
  const contentId = React.useId();
  const statusLabel = STATUS_LABELS[status] || status;

  return (
    <div
      className={cn(
        "rounded-lg border overflow-hidden",
        "bg-[var(--axis-surface-default)] border-[var(--axis-border-default)]",
        className
      )}
    >
      {/* 헤더 */}
      <button
        onClick={() => setIsExpanded(!isExpanded)}
        aria-expanded={isExpanded}
        aria-controls={contentId}
        aria-label={ariaLabel || `${toolName} - ${statusLabel}`}
        className="w-full flex items-center justify-between p-3 hover:bg-[var(--axis-surface-secondary)] transition-colors"
      >
        <div className="flex items-center gap-2">
          <span className={config.color} aria-hidden="true">{config.icon}</span>
          <code className="text-sm font-mono text-[var(--axis-text-primary)]">
            {toolName}
          </code>
          {description && (
            <span className="text-xs text-[var(--axis-text-secondary)]">
              — {description}
            </span>
          )}
        </div>
        <div className="flex items-center gap-2">
          {duration !== undefined && (
            <span className="text-xs text-[var(--axis-text-tertiary)]">
              {duration}ms
            </span>
          )}
          <svg
            className={cn(
              "w-4 h-4 text-[var(--axis-text-secondary)] transition-transform",
              isExpanded && "rotate-180"
            )}
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
          </svg>
        </div>
      </button>

      {/* 내용 */}
      {isExpanded && (
        <div id={contentId} className="border-t border-[var(--axis-border-default)] p-3 space-y-3">
          {input && (
            <div>
              <h5 className="text-xs font-medium text-[var(--axis-text-secondary)] mb-1">
                입력
              </h5>
              <pre className="text-xs p-2 rounded bg-[var(--axis-surface-secondary)] overflow-x-auto">
                <code className="text-[var(--axis-text-primary)]">
                  {JSON.stringify(input, null, 2)}
                </code>
              </pre>
            </div>
          )}
          {output !== undefined && (
            <div>
              <h5 className="text-xs font-medium text-[var(--axis-text-secondary)] mb-1">
                출력
              </h5>
              <pre className="text-xs p-2 rounded bg-[var(--axis-surface-secondary)] overflow-x-auto">
                <code className="text-[var(--axis-text-primary)]">
                  {typeof output === "string" ? output : JSON.stringify(output, null, 2)}
                </code>
              </pre>
            </div>
          )}
          {error && (
            <div>
              <h5 className="text-xs font-medium text-[var(--axis-text-error)] mb-1">
                에러
              </h5>
              <pre className="text-xs p-2 rounded bg-[var(--axis-surface-error)] overflow-x-auto">
                <code className="text-[var(--axis-text-error)]">{error}</code>
              </pre>
            </div>
          )}
        </div>
      )}
    </div>
  );
}
